// ── Desert Cubs: Build weekly Gemini prompt ──────────────────────────────
// Cycles through 11 target keywords so each week focuses on a different one.
// Edit the list below whenever your SEO strategy changes.

const today = new Date();
const dateStr = today.toISOString().slice(0, 10);

const TARGET_KEYWORDS = [
  'UAE Junior Cricket Coaching',
  'Sharjah Junior Cricket Coaching',
  'UAE Summer Camp Cricket',
  'Best Cricket Academy in UAE',
  'Best Cricket Academy in Dubai',
  'UAE National Cricket Player Pathway',
  'Best Cricket Ground in UAE',
  'Advanced Player Analysis Junior Cricket UAE',
  'Junior International Cricket Tournament UAE',
  'Junior International Cricket Tour UAE',
  'Most Cricket Tournaments in UAE'
];

const weekNumber = Math.floor(Date.now() / (7 * 24 * 60 * 60 * 1000));
const focusKeyword = TARGET_KEYWORDS[weekNumber % TARGET_KEYWORDS.length];

const systemPrompt = `You are an expert SEO content writer for Desert Cubs Cricket Academy — UAE's best junior cricket academy at www.desertcubs.com. Founded 2007. 15,000+ alumni. 6 training centres across Dubai and Sharjah. ICC-certified coaches. Ages 4–19. Write content that is genuinely helpful to UAE parents and junior cricketers.`;

const userPrompt = `Today's date: ${dateStr}
This week's SEO focus keyword: "${focusKeyword}"

Write a brand new weekly blog post for Desert Cubs Cricket Academy.

Requirements:
- Minimum 500 words
- Use the focus keyword and related terms naturally
- Include practical tips UAE parents or players will find useful
- Mention Desert Cubs naturally — not spam
- End with a clear call-to-action to enrol or contact Desert Cubs

Return ONLY a valid JSON object (no markdown, no code block, pure JSON) with exactly these keys:
{
  "seo_keywords": ["kw1", "kw2", "kw3", "kw4", "kw5", "kw6", "kw7", "kw8"],
  "seo_title": "SEO page title with focus keyword — under 70 characters",
  "seo_description": "Meta description with focus keyword — under 160 characters",
  "blog_title": "Engaging, readable blog post title",
  "image_prompt": "Realistic photography prompt for a wide banner image — describe the cricket scene in UAE (children training, academy setting, desert light). NO text or logos in image.",
  "blog_html": "Full HTML body content using ONLY h2, h3, p, ul, li, strong tags. No html/head/body wrapper. Minimum 500 words."
}`;

const geminiRequest = {
  system_instruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { responseMimeType: 'application/json' }
};

return [{ json: { geminiRequest, focusKeyword, dateStr } }];

// ── Parse Gemini response & prepare all file payloads ────────────────────
const geminiResponse = $input.first().json;
const buildStep = $('Build Gemini Prompt').first().json;

// Gemini returns: candidates[0].content.parts[0].text
let parsed;
try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch(e) {
  throw new Error('Failed to parse Gemini JSON response: ' +
    JSON.stringify(geminiResponse).slice(0, 400));
}

// Validate all required fields exist
const REQUIRED = ['seo_keywords', 'seo_title', 'seo_description', 'blog_title', 'image_prompt', 'blog_html'];
for (const field of REQUIRED) {
  if (!parsed[field]) throw new Error(`Gemini response missing field: ${field}`);
}

// ── Build slug matching Flask app.py convention: YYYY-MM-DD_slug-title ──
const slugPart = parsed.blog_title
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .slice(0, 55)
  .replace(/-$/g, '');
const slug = `${buildStep.dateStr}_${slugPart}`;

// ── File paths for GitHub API (exact paths in the repo) ──
const blogFilePath  = `content/posts/${slug}.html`;
const imageFilePath = `static/img/blog/${slug}.jpg`;

// ── Build seo.json content ──
const seoContent = JSON.stringify({
  title:       parsed.seo_title,
  description: parsed.seo_description,
  keywords:    Array.isArray(parsed.seo_keywords)
                 ? parsed.seo_keywords.join(', ')
                 : parsed.seo_keywords
}, null, 2);

// ── Base64 encode text files for GitHub API ──
const blogBase64 = Buffer.from(parsed.blog_html, 'utf-8').toString('base64');
const seoBase64  = Buffer.from(seoContent, 'utf-8').toString('base64');

// ── Pollinations.ai free image URL (no API key needed) ──
const imagePromptEncoded = encodeURIComponent(parsed.image_prompt);
const pollinationsUrl = `https://image.pollinations.ai/prompt/${imagePromptEncoded}?width=1280&height=640&nologo=true&seed=${Date.now()}`;

return [{
  json: {
    slug,
    blogFilePath,
    imageFilePath,
    blogBase64,
    seoBase64,
    pollinationsUrl,
    blogTitle:    parsed.blog_title,
    focusKeyword: buildStep.focusKeyword,
    dateStr:      buildStep.dateStr,
    commitBlog:   `auto(n8n): new blog – ${parsed.blog_title}`,
    commitImage:  `auto(n8n): blog banner image – ${slug}.jpg`,
    commitSeo:    `auto(n8n): SEO keywords update ${buildStep.dateStr} – ${buildStep.focusKeyword}`
  }
}];

// ── Extract base64 image from Pollinations binary response ────────────────
// N8N stores downloaded binary files in item.binary.data.data (base64 string)
const item = $input.first();

let imageBase64;
try {
  imageBase64 = item.binary.data.data;
  if (!imageBase64) throw new Error('binary.data.data is empty');
} catch(e) {
  throw new Error('Could not extract binary image from Pollinations response. ' + e.message);
}

// Merge image base64 with all blog/SEO data from the Parse step
const parseData = $('Parse & Build Payloads').first().json;

return [{
  json: {
    ...parseData,
    imageBase64
  }
}];
